task.action:
- Create terminal directory: apps/vscode/src/terminal/
- Create kanban-terminal.ts with KanbanPseudoterminal class
- Implement VSCode Pseudoterminal interface (open, close, handleInput)
- Use writeEmitter/closeEmitter EventEmitters for terminal output
- Spawn Claude CLI via child_process.spawn with FORCE_COLOR and TERM env vars
- Buffer stdout/stderr, detect [KANBAN_COMPLETE] marker
- Call onComplete callback with exit code when marker detected or process exits
- Wait 1500ms after marker detection before killing process (FR3 visibility delay)
- Export factory function createKanbanTerminal(cwd, command, taskId, onComplete)

Current code (compiled JS at out/terminal/kanban-terminal.js):
```javascript
class KanbanPseudoterminal {
  constructor(cwd, command, onComplete) {
    this.writeEmitter = new vscode.EventEmitter();
    this.closeEmitter = new vscode.EventEmitter();
    // ...
  }
  checkForCompletion(text) {
    if (this.outputBuffer.includes('[KANBAN_COMPLETE]')) {
      this.onComplete();
      setTimeout(() => this.killProcess(), 500);
    }
  }
}
```

Change to TypeScript with explicit types and 1500ms delay:
```typescript
export interface KanbanPseudoterminalDeps {
  cwd: string;
  command: string;
  onComplete: (exitCode: number) => void;
}

export class KanbanPseudoterminal implements vscode.Pseudoterminal {
  private readonly writeEmitter = new vscode.EventEmitter();
  private readonly closeEmitter = new vscode.EventEmitter();
  readonly onDidWrite = this.writeEmitter.event;
  readonly onDidClose = this.closeEmitter.event;

  private process: ChildProcess | null = null;
  private outputBuffer = '';
  private completionDetected = false;

  constructor(private readonly deps: KanbanPseudoterminalDeps) {}

  // onComplete receives exit code for FR11
  private checkForCompletion(text: string): void {
    if (this.completionDetected) return;
    this.outputBuffer += text;
    if (this.outputBuffer.length > 4000) {
      this.outputBuffer = this.outputBuffer.slice(-4000);
    }
    if (this.outputBuffer.includes('[KANBAN_COMPLETE]')) {
      this.completionDetected = true;
      // FR3: 1500ms delay for visibility
      setTimeout(() => this.killProcess(), 1500);
    }
  }
}

export function createKanbanTerminal(
  workspaceRoot: string,
  command: string,
  taskId: string,
  onComplete?: (exitCode: number) => void
): vscode.Terminal
```

