- Create autoplay state tracking: currentTaskId, autoplayTerminal
- In onComplete callback for kanban.runAction and kanban.runNextAction:
  1. Check exitCode !== 0: stop autoplay (FR11)
  2. Check kanban.autoplay setting is enabled (FR8)
  3. Re-read task.xml to get current status (FR5)
  4. Check if isSinglePathStatus(status) (FR6, FR7)
  5. If all pass: get primary action, create new terminal, trigger next action
  6. If any fail: stop autoplay chain
- Handle terminal closure detection: use vscode.window.onDidCloseTerminal
  to clear autoplayTerminal reference and stop chain (FR9)

Add to extension.ts:
```typescript
// Autoplay state (orchestrator owns state)
let autoplayTaskId: string | undefined;
let autoplayTerminal: vscode.Terminal | undefined;

// Handle terminal closure (FR9)
context.subscriptions.push(
  vscode.window.onDidCloseTerminal((closedTerminal) => {
    if (closedTerminal === autoplayTerminal) {
      autoplayTaskId = undefined;
      autoplayTerminal = undefined;
      // Hide status bar item
    }
  })
);

// In onComplete callback:
function handleAutoplay(taskId: string, exitCode: number): void {
  // FR11: Stop on error
  if (exitCode !== 0) {
    autoplayTaskId = undefined;
    return;
  }

  // FR8: Check setting
  const config = vscode.workspace.getConfiguration('kanban');
  if (!config.get('autoplay')) {
    autoplayTaskId = undefined;
    return;
  }

  // FR5: Re-read task status
  const taskPath = fs.joinPath(kanbanDir, 'tasks', taskId);
  const taskXml = fs.joinPath(taskPath, 'task.xml');
  const content = fs.readFile(taskXml);
  const task = taskParser.parseTaskWithPath(content, taskPath);

  // FR6, FR7: Check if single-path
  if (!taskActions.isSinglePathStatus(task.status)) {
    autoplayTaskId = undefined;
    return;
  }

  // Get primary action and trigger
  const actions = taskActions.getActions(task);
  if (actions.length === 0) {
    autoplayTaskId = undefined;
    return;
  }

  autoplayTaskId = taskId;
  autoplayTerminal = createKanbanTerminal(
    workspaceRoot,
    actions[0].command,
    taskId,
    (code) => handleAutoplay(taskId, code)
  );
}
```

- Create status bar item in activate(): vscode.window.createStatusBarItem
- Show spinning icon with task ID: "$(sync~spin) Autoplay: task {id}"
- Show status bar when autoplay starts, hide when it stops
- Update status bar text when task transitions
- Dispose status bar on deactivate

Add to extension.ts:
```typescript
// Create status bar item
const autoplayStatusBar = vscode.window.createStatusBarItem(
  vscode.StatusBarAlignment.Left,
  100
);
context.subscriptions.push(autoplayStatusBar);

function showAutoplayStatus(taskId: string): void {
  autoplayStatusBar.text = '$(sync~spin) Autoplay: task ' + taskId;
  autoplayStatusBar.tooltip = 'Autoplay is running. Close terminal to stop.';
  autoplayStatusBar.show();
}

function hideAutoplayStatus(): void {
  autoplayStatusBar.hide();
}

// In handleAutoplay: call showAutoplayStatus when starting
// In terminal close handler and stop conditions: call hideAutoplayStatus
```
